// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 depositAmount, bool accept) public {
        depositAmount = bound(depositAmount, 1, 1 ether);

        Adversary adv = accept ? new Adversary(true) : new Adversary(false);

        vm.deal(address(this), 2 ether);

        vm.deal(address(adv), depositAmount);
        vm.prank(address(adv));
        c.deposit{value: depositAmount}();

        uint256 beforeBal = address(c).balance;

        bool ok;
        vm.prank(address(adv));
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(
            (ok && address(c).balance == beforeBal - depositAmount) || (!ok && address(c).balance == beforeBal)
        );
    }
}

contract Adversary {
    bool public willAccept;
    constructor(bool _willAccept) payable { willAccept = _willAccept; }
    receive() external payable {
        if (!willAccept) revert("nope");
    }
}
